static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
{
  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
  ssize_t packet_len;
  int ret;

  if (data == NULL || len == 0)
    {
      return -EINVAL;
    }

  syslog(LOG_ERR, "[BTDBG] HCI RX callback len=%u first=%02x drop=%d\\n",
         len, data[0], priv->drop_rx_until_tx ? 1 : 0);

