   194	static void reset_rx(struct h4_data *h4)
   195	{
   196		h4->rx.type = BT_HCI_H4_NONE;
   197		h4->rx.remaining = 0U;
   198		h4->rx.have_hdr = false;
   199		h4->rx.hdr_len = 0U;
   200		h4->rx.discardable = false;
   201	}
