   314	static int h4_send(const struct device *dev, struct net_buf *buf)
   315	{
   316		struct h4_data *h4 = dev->data;
   317		int len;
   318		int ret;
   319	
   320		syslog(3, "[BTDBG] H4 send type=%u len=%u\n",
   321		       (unsigned int)bt_buf_get_type(buf), (unsigned int)buf->len);
   322	
   323		LOG_DBG("buf %p type %u len %u", buf, bt_buf_get_type(buf), buf->len);
   324	
   325		switch (bt_buf_get_type(buf)) {
   326		case BT_BUF_ACL_OUT:
   327			net_buf_push_u8(buf, BT_HCI_H4_ACL);
   328			break;
   329		case BT_BUF_CMD:
   330			net_buf_push_u8(buf, BT_HCI_H4_CMD);
   331			break;
   332		case BT_BUF_ISO_OUT:
   333			if (IS_ENABLED(CONFIG_BT_ISO)) {
   334				net_buf_push_u8(buf, BT_HCI_H4_ISO);
   335				break;
   336			}
   337			__fallthrough;
   338		default:
   339			LOG_ERR("Unknown buffer type");
   340			return -EINVAL;
   341		}
   342	
   343		h4_data_dump("BT TX", buf->data[0], buf->data + 1, buf->len - 1);
   344	
   345		pthread_mutex_lock(&h4->mutex);
   346		len = buf->len;
   347		btsnoop_log_capture(0, buf->data, buf->len);
   348		ret = h4_send_data(h4, buf->data, buf->len);
   349		syslog(3, "[BTDBG] H4 write ret=%d len=%d\n", ret, len);
   350		if (ret != len) {
   351			ret = -EINVAL;
   352		}
   353	
   354		net_buf_unref(buf);
   355		pthread_mutex_unlock(&h4->mutex);
   356	
   357		return ret < 0 ? ret : 0;
   358	}
