   360	static int h4_open(const struct device *dev, bt_hci_recv_t recv, void *hci_data)
   361	{
   362		int ret;
   363		struct h4_data *h4 = dev->data;
   364		char dev_name[32];
   365	
   366		if (dev->name == NULL) {
   367			LOG_ERR("No device name");
   368			return -EINVAL;
   369		}
   370	
   371		ret = snprintf(dev_name, sizeof(dev_name), "%s", dev->name);
   372		if (ret < 0 || ret >= sizeof(dev_name)) {
   373			LOG_ERR("dev_name:%s snprintf failed, ret %d, ", dev->name, ret);
   374			return -EINVAL;
   375		}
   376	
   377		ret = file_open(&h4->filep, dev_name, O_RDWR | O_BINARY);
   378		if (ret < 0) {
   379			goto bail;
   380		}
   381	
   382		syslog(3, "[BTDBG] H4 open %s\n", dev_name);
   383		LOG_DBG("H4: %s opened", dev_name);
   384	
   385		ret = (int)k_thread_create(&h4->rx_thread_data, h4->rx_thread_stack,
   386					   K_THREAD_STACK_SIZEOF(h4->rx_thread_stack), h4_rx_thread, (void *)dev, NULL,
   387					   NULL, K_PRIO_COOP(CONFIG_BT_RX_PRIO), 0, K_NO_WAIT);
   388	
   389		if (ret < 0) {
   390			goto bail;
   391		} else {
   392			ret = 0;
   393		}
   394	
   395		h4->recv = recv;
   396		h4->hci_data = hci_data;
   397	
   398		ret = snprintf(dev_name, sizeof(dev_name), "BT Driver %s", dev->name);
   399		if (ret < 0 || ret >= sizeof(dev_name)) {
   400			LOG_ERR("dev_name:%s snprintf failed, ret %d, ", dev->name, ret);
   401			return -EINVAL;
   402		}
   403	
   404		k_thread_name_set(&h4->rx_thread_data, dev_name);
   405		LOG_DBG("returning");
   406	
   407		return 0;
   408	
   409	bail:
   410		file_close(&h4->filep);
   411	
   412		return ret;
   413	}
   414	
   415	static int h4_close(const struct device *dev)
   416	{
   417		struct h4_data *h4 = dev->data;
   418	
   419		LOG_DBG("close h4");
   420	
   421		k_thread_abort(&h4->rx_thread_data);
   422	
   423		file_close(&h4->filep);
   424	
   425		return 0;
   426	}
